#include <windows.h>
#include <string.h>
#include "user_mapping_session.h"
#include "user_mapping_internal.h"
typedef struct MappingSessionRow {volatile LONG published,pending,done,in_request,has_key;uint32_t serial,reason;UserMappingKey key;} MappingSessionRow;
static UserMappingSessionConfig policy;static volatile LONG configured,rows,current,fatal;
static MappingSessionRow records[UM_SESSION_CAPACITY];
static uint32_t load(volatile LONG*p){return (uint32_t)InterlockedCompareExchange(p,0,0);}
static int main_now(void){return GetCurrentThreadId()==policy.main_thread;}
static MappingSessionRow *find(uint32_t serial){for(unsigned i=0;i<UM_SESSION_CAPACITY;++i)if(load(&records[i].published)&&records[i].serial==serial)return records+i;return NULL;}
int user_mapping_session_configure(const UserMappingSessionConfig*c){DWORD e=GetLastError();int ok=0;if(c&&c->version==1&&c->main_thread&&c->safe_main_valid&&c->current_session&&InterlockedCompareExchange(&configured,-1,0)==0){policy=*c;InterlockedExchange(&configured,1);ok=1;}SetLastError(e);return ok;}
int user_mapping_session_retire(uint32_t serial,uint32_t reason){DWORD e=GetLastError();MappingSessionRow*r=find(serial);int ok=r!=NULL;if(r){InterlockedOr((volatile LONG*)&r->reason,(LONG)reason);InterlockedExchange(&r->pending,1);}SetLastError(e);return ok;}
int user_mapping_session_begin(uint32_t serial){DWORD e=GetLastError();int ok=0;if(load(&configured)!=1||!main_now()||!serial||load(&fatal)||policy.current_session(policy.user)!=serial)goto done;MappingSessionRow*r=find(serial);if(r){ok=!load(&r->pending)&&!load(&r->done);goto done;}if(serial<load(&current)||load(&rows)>=UM_SESSION_CAPACITY){InterlockedExchange(&fatal,1);goto done;}for(unsigned i=0;i<UM_SESSION_CAPACITY;++i)if(load(&records[i].published)&&!load(&records[i].done))user_mapping_session_retire(records[i].serial,1);
 r=records+load(&rows);memset(r,0,sizeof(*r));r->serial=serial;MemoryBarrier();InterlockedExchange(&r->published,1);InterlockedIncrement(&rows);InterlockedExchange(&current,(LONG)serial);ok=1;done:SetLastError(e);return ok;}
int user_mapping_session_pending(void){for(unsigned i=0;i<UM_SESSION_CAPACITY;++i){MappingSessionRow*r=records+i;if(load(&r->published)&&load(&r->pending)&&!load(&r->done)&&(load(&r->in_request)||load(&r->has_key)))return 1;}return 0;}
int __cdecl user_mapping_session_acquire_begin(MappingSessionAcquire*s,uint32_t serial,const UserMappingRequest*request){DWORD e=GetLastError();memset(s,0,sizeof(*s));int ok=0;if(load(&configured)!=1||!main_now()||load(&fatal)||policy.current_session(policy.user)!=serial||user_mapping_session_pending())goto done;MappingSessionRow*r=find(serial);if(!r||load(&r->pending)||load(&r->done)||load(&r->in_request)||!request)goto done;
 if(load(&r->has_key)){UserMappingObservation o;if(!user_mapping_inspect(r->key,&o))goto done;if(o.quality&UM_Q_CURRENT_VALUE)goto done;user_mapping_retire(r->key);InterlockedExchange(&r->has_key,0);}
 s->row=r;s->session_serial=serial;s->entered=1;InterlockedIncrement(&r->in_request);ok=1;done:SetLastError(e);return ok;}
void __cdecl user_mapping_session_acquire_end(MappingSessionAcquire*s,int unwind){DWORD e=GetLastError();if(s->entered){MappingSessionRow*r=s->row;if(r&&load(&r->published)&&r->serial==s->session_serial){UserMappingTicket ticket;if(s->key.id&&user_mapping_ticket_get(s->key,&ticket)&&!(ticket.flags&UM_T_NOT_SENT)){r->key=s->key;MemoryBarrier();InterlockedExchange(&r->has_key,1);}if(unwind)InterlockedExchange(&r->pending,1);InterlockedDecrement(&r->in_request);}}SetLastError(e);}
int user_mapping_session_device_get(uint32_t serial,UserMappingObservation*out){DWORD e=GetLastError();int ok=0;if(load(&configured)==1&&main_now()&&!load(&fatal)&&policy.current_session(policy.user)==serial){MappingSessionRow*r=find(serial);if(r&&!load(&r->pending)&&!load(&r->done)&&load(&r->has_key)&&user_mapping_inspect(r->key,out)){ok=(out->quality&UM_Q_CURRENT_VALUE)!=0&&policy.current_session(policy.user)==serial&&!load(&r->pending);if(ok){if(!user_mapping_mutation_try())ok=0;else{int32_t saved;ok=user_mapping_cleanup_owned(r->key,&saved)==1;user_mapping_mutation_unlock();}}}}SetLastError(e);return ok;}
int __cdecl user_mapping_session_drain_begin(MappingSessionDrain*s,const void*boundary,uint32_t bytes,uint32_t observed){DWORD e=GetLastError();memset(s,0,sizeof(*s));int result=UM_DRAIN_IDLE;if(load(&configured)!=1||!main_now()||load(&fatal))return UM_DRAIN_UNPROVED;if(!bytes||bytes>sizeof(s->boundary)||!user_mapping_install_ready()||!policy.safe_main_valid(boundary,bytes,policy.user)||policy.current_session(policy.user)!=observed){result=UM_DRAIN_DEFERRED;goto done;}
 memcpy(s->boundary,boundary,bytes);s->boundary_bytes=bytes;s->observed=observed;
 MappingSessionRow*r=NULL;for(unsigned i=0;i<UM_SESSION_CAPACITY;++i)if(load(&records[i].published)&&load(&records[i].pending)&&!load(&records[i].done)){r=records+i;break;}if(!r)goto done;s->row=r;if(load(&r->in_request)){result=UM_DRAIN_DEFERRED;goto done;}if(!load(&r->has_key)){InterlockedExchange(&r->done,1);goto done;}
 UserMappingObservation o;if(!user_mapping_inspect(r->key,&o)||o.disabled){InterlockedExchange(&fatal,1);result=UM_DRAIN_UNPROVED;goto done;}if(!(o.ticket.flags&UM_T_MAPPING_COMMITTED)){InterlockedExchange(&fatal,1);result=UM_DRAIN_UNPROVED;goto done;}
 if(!user_mapping_mutation_try()){result=UM_DRAIN_DEFERRED;goto done;}s->locked=1;
 if(!policy.safe_main_valid(boundary,bytes,policy.user)||policy.current_session(policy.user)!=observed||!user_mapping_install_ready()){result=UM_DRAIN_DEFERRED;goto done;}
 int owned=user_mapping_cleanup_owned(r->key,&s->negative);if(owned<0){user_mapping_retire(r->key);InterlockedExchange(&r->done,1);result=UM_DRAIN_MOVED;goto done;}if(!owned){result=UM_DRAIN_DEFERRED;goto done;}
 if(!policy.safe_main_valid(boundary,bytes,policy.user)||policy.current_session(policy.user)!=observed){result=UM_DRAIN_DEFERRED;goto done;}
 if(!user_mapping_cleanup_consume(r->key)){InterlockedExchange(&fatal,1);result=UM_DRAIN_UNPROVED;goto done;}s->consumed=1;result=UM_DRAIN_RESTORED;
 done:SetLastError(e);return result;}
int __cdecl user_mapping_session_drain_complete(MappingSessionDrain*s){DWORD e=GetLastError();int result=UM_DRAIN_IDLE;if(s->consumed){MappingSessionRow*r=s->row;if(!user_mapping_runtime_ready()||!policy.safe_main_valid(s->boundary,s->boundary_bytes,policy.user)||policy.current_session(policy.user)!=s->observed){if(r)InterlockedExchange(&r->done,1);result=UM_DRAIN_RESTORED_RECHECK;}else if(user_mapping_native_saved_matches(s->negative)){if(r)InterlockedExchange(&r->done,1);result=UM_DRAIN_RESTORED;}else{InterlockedExchange(&fatal,1);result=UM_DRAIN_UNPROVED;}}SetLastError(e);return result;}
int __cdecl user_mapping_session_drain_end(MappingSessionDrain*s,int unwind){DWORD e=GetLastError();int result=UM_DRAIN_IDLE;if(s->consumed&&unwind){InterlockedExchange(&fatal,1);result=UM_DRAIN_CONSUMED_UNWIND;}if(s->locked){s->locked=0;user_mapping_mutation_unlock();}SetLastError(e);return result;}
